    (r'TOTAL\s+SALES', 83),
    (r'ROUNDED\s+TOTAL', 82),
    (r'TOTAL\s+ROUNDED', 82),
    (r'TOTAL\s+AMT', 82),
    (r'TOTAL\s+INCL', 80),
    (r'TOTAL\s+INCLUSIVE', 80),
    (r'TOTAL\s+DUE', 78),
    (r'AMOUNT\s+DUE', 78),
    (r'BALANCE\s+DUE', 78),
    (r'NETT?\s+TOTAL', 76),
    (r'NET\s+TOTAL', 76),
    (r'TOTAL', 60),
    (r'AMOUNT', 50),
]

exclusions_strict = ['SUBTOTAL','SUB TOTAL','DISCOUNT','CHANGE','CASH TENDERED','EXCLUDING','EXCL']
exclusions_soft = ['TAX','GST','SST']

month_map = {m:i for i,m in enumerate(['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'], start=1)}


def ocr_variants(path: Path):
    img = Image.open(path)
    texts = []
    texts.append(pytesseract.image_to_string(img, config='--psm 6'))
    g = ImageOps.grayscale(img)
    g = ImageOps.autocontrast(g)
    texts.append(pytesseract.image_to_string(g, config='--psm 6'))
    t = g.filter(ImageFilter.SHARPEN)
    t = t.point(lambda x: 0 if x < 180 else 255)
    texts.append(pytesseract.image_to_string(t, config='--psm 6'))
    texts.append(pytesseract.image_to_string(img, config='--psm 11'))
    return texts


def parse_date_from_text(text: str):
    lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
    date_candidates = []

    def add_matches(s, base_pos=0):
        for m in re.finditer(r'(?<!\d)(\d{1,2})[\-/\.](\d{1,2})[\-/\.](\d{4})(?!\d)', s):
            d,mn,y = map(int, m.groups())
            if 1 <= d <= 31 and 1 <= mn <= 12:
                date_candidates.append((base_pos + m.start(), y, mn, d))
        for m in re.finditer(r'(?<!\d)(\d{4})[\-/\.](\d{1,2})[\-/\.](\d{1,2})(?!\d)', s):
            y,mn,d = map(int, m.groups())
            if 1 <= d <= 31 and 1 <= mn <= 12:
                date_candidates.append((base_pos + m.start(), y, mn, d))
        for m in re.finditer(r'(?<!\d)(\d{1,2})[\-/\.](\d{1,2})[\-/\.](\d{2})(?!\d)', s):
            d,mn,y2 = map(int, m.groups())
            if 1 <= d <= 31 and 1 <= mn <= 12:
                y = 2000 + y2 if y2 <= 79 else 1900 + y2
                date_candidates.append((base_pos + m.start(), y, mn, d))
        for m in re.finditer(r'(?<!\w)(\d{1,2})\s*([A-Za-z]{3,9})\s*(\d{4})(?!\d)', s):
            d = int(m.group(1))
            mn_str = m.group(2)[:3].upper()
            y = int(m.group(3))
            mn = month_map.get(mn_str)
            if mn and 1 <= d <= 31:
                date_candidates.append((base_pos + m.start(), y, mn, d))

    # prefer lines with DATE
    for idx, line in enumerate(lines):
        if 'DATE' in line.upper():
            add_matches(line, base_pos=idx * 1000)
    if not date_candidates:
        add_matches(text)
    if not date_candidates:
        return None
    date_candidates.sort(key=lambda x: x[0])
    # prefer reasonable year range
    for _, y, mn, d in reversed(date_candidates):
        if 1990 <= y <= 2030:
            return f"{y:04d}-{mn:02d}-{d:02d}"
    y, mn, d = date_candidates[-1][1:]
    return f"{y:04d}-{mn:02d}-{d:02d}"


def parse_number(num: str):
    if ',' in num and '.' not in num:
        if num.count(',') == 1 and len(num.split(',')[1]) == 2:
            num = num.replace(',', '.')
        else:
            num = num.replace(',', '')
    else:
        num = num.replace(',', '')
    try:
        dec = Decimal(num)
    except InvalidOperation:
        return None
    return f"{dec:.2f}"


def extract_amount_from_line(line: str):
    # normalize dot/comma between digits
    cleaned = re.sub(r'(?<=\d)\s*[\.,]\s*(?=\d)', '.', line)
    nums = re.findall(r'(?<!\d)(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d{1,2})?(?!\d)', cleaned)
    if nums:
        # handle pattern like "92 80" -> combine last two tokens
        if len(nums) >= 2 and nums[-1].isdigit() and len(nums[-1]) == 2 and '.' not in nums[-2]:
            combined = f"{nums[-2]}.{nums[-1]}"
            parsed = parse_number(combined)
            if parsed:
                return parsed
        parsed = parse_number(nums[-1])
        if parsed:
            return parsed
    # fallback: look for two tokens like "92 80" not captured
    tokens = re.findall(r'\d+', cleaned)
    if len(tokens) >= 2 and len(tokens[-1]) == 2:
        combined = f"{tokens[-2]}.{tokens[-1]}"
        return parse_number(combined)
    return None


