    if 'SUMMARY' in line_upper:
        return True
    if any(ex in line_upper for ex in exclusions_strict):
        return True
    if pat in ('TOTAL', 'AMOUNT'):
        if any(ex in line_upper for ex in exclusions_soft):
            return True
    return False


def extract_amount_from_text(text: str):
    lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
    candidates = []
    total_lines = len(lines) or 1
    for i, line in enumerate(lines):
        up = line.upper()
        for pat, score in patterns:
            if re.search(pat, up):
                if should_skip(up, pat):
                    continue
                amt = extract_amount_from_line(line)
                if not amt and i + 1 < len(lines):
                    amt = extract_amount_from_line(lines[i+1])
                if amt:
                    pos_score = (i / total_lines) * 5
                    candidates.append((score + pos_score, amt))
                    break
    if not candidates:
        return None
    candidates.sort(key=lambda x: x[0], reverse=True)
    return candidates[0][1]


def extract_date_from_variants(texts):
    # choose first variant with DATE line match
    for text in texts:
        lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
        has_date_line = any('DATE' in ln.upper() for ln in lines)
        if has_date_line:
            date = parse_date_from_text(text)
            if date:
                return date
    # fallback to majority
    dates = [parse_date_from_text(t) for t in texts if t.strip()]
    dates = [d for d in dates if d]
    if not dates:
        return None
    return Counter(dates).most_common(1)[0][0]


def extract_total_from_variants(texts):
    totals = [extract_amount_from_text(t) for t in texts if t.strip()]
    totals = [t for t in totals if t]
    if not totals:
        return None
    return Counter(totals).most_common(1)[0][0]


rows = []
for path in sorted(img_dir.glob('*.jpg')):
    texts = ocr_variants(path)
    date = extract_date_from_variants(texts)
    total = extract_total_from_variants(texts)
    rows.append({'filename': path.name, 'date': date, 'total_amount': total})

# write to excel

df = pd.DataFrame(rows, columns=['filename','date','total_amount'])
with pd.ExcelWriter(output_path, engine='openpyxl') as writer:
    df.to_excel(writer, sheet_name='results', index=False)

print('Wrote', output_path)
